controls.state_control.ps1:
param([Parameter(Mandatory=$true)][ValidateSet('Observe','Ready','AllowStop','Off')][string]$Mode)
$ErrorActionPreference='Stop'
$taskRoot='C:\Users\w.filho\AppData\Local\Temp\maskgw-oracle9-process-20261026-f6c89e76'
$statePath=Join-Path $taskRoot 'attempt.json'
$state=Get-Content -LiteralPath $statePath -Raw -Encoding UTF8 | ConvertFrom-Json
if($state.kind -ne 'maskgw-oracle9-process' -or $state.task -ne 'b2f6ae6f557943fbadde9da9705cc85f'){throw 'STATE_IDENTITY'}
function Write-Atomic($path,$value){
 $data=[Text.UTF8Encoding]::new($false).GetBytes(($value|ConvertTo-Json -Depth 8))
 $temp=$path+'.next'
 $stream=[IO.FileStream]::new($temp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
 try{$stream.Write($data,0,$data.Length);$stream.Flush($true)}finally{$stream.Dispose()}
 if([IO.File]::Exists($path)){[IO.File]::Replace($temp,$path,[NullString]::Value)}else{[IO.File]::Move($temp,$path)}
}
function Check-AppIdentity{
 if($state.desktop_started_by_attempt -eq $true){
  $app=Get-Process -Id $state.launch_pid -ErrorAction Stop
  if($app.StartTime.ToUniversalTime().ToFileTimeUtc() -ne [int64]$state.launch_time){throw 'APP_IDENTITY'}
 }
}
$observationsPath=Join-Path $taskRoot 'observations.json'
if($Mode -eq 'Observe'){
 if($state.phase -ne 'APP_OBSERVED' -or $state.invoked -ne $false){throw 'STATE_PHASE'}
 try{
  $rows=@()
  if([IO.File]::Exists($observationsPath)){
   $parsed=Get-Content -LiteralPath $observationsPath -Raw -Encoding UTF8|ConvertFrom-Json
   $rows=@($parsed)
  }
  if($rows.Count -notin @(0,3,6)){throw 'OBSERVATION_COUNT'}
  for($index=0;$index -lt 3;$index++){
   Start-Sleep -Seconds 10
   Check-AppIdentity
   $processes=@(Get-Process|Where-Object{$_.ProcessName -match 'docker'})
   if($processes.Count -eq 0){throw 'APP_ABSENT'}
   $rows+=@([pscustomobject]@{utc=[DateTime]::UtcNow.ToString('o');DockerProcessCount=$processes.Count;sameIdentity=($state.desktop_started_by_attempt -eq $true)})
  }
  Write-Atomic $observationsPath @($rows)
  $rows|Select-Object -Last 3|ConvertTo-Json -Depth 4
 }catch{
  $state.phase='OBSERVE_FAILED'
  Write-Atomic $statePath $state
  throw
 }
}elseif($Mode -eq 'Ready'){
 if($state.phase -ne 'APP_OBSERVED' -or $state.invoked -ne $false){throw 'STATE_PHASE'}
 Check-AppIdentity
 $parsed=Get-Content -LiteralPath $observationsPath -Raw -Encoding UTF8|ConvertFrom-Json
 $rows=@($parsed)
 if($rows.Count -ne 9 -or @($rows|Where-Object{$_.DockerProcessCount -le 0 -or ($state.desktop_started_by_attempt -eq $true -and $_.sameIdentity -ne $true)}).Count -ne 0){throw 'OBSERVATIONS'}
 $state.phase='APP_READY'
 $state|Add-Member -NotePropertyName observations -NotePropertyValue 9
 $state|Add-Member -NotePropertyName minimum_commanded_wait_seconds -NotePropertyValue 90
 Write-Atomic $statePath $state
 $state|ConvertTo-Json -Depth 4
}elseif($Mode -eq 'AllowStop'){
 if($state.desktop_initial -ne 'off' -or $state.desktop_started_by_attempt -ne $true -or $state.invoked -ne $true -or $state.PSObject.Properties.Name -contains 'restore_invoked'){throw 'STOP_OWNERSHIP'}
 Check-AppIdentity
 $result=Get-Content -LiteralPath (Join-Path $taskRoot 'result.json') -Raw -Encoding UTF8|ConvertFrom-Json
 if($result.profile -ne 'oracle9-process' -or $result.task -ne $state.task -or $result.owned_cleanup -ne $true -or $result.inventory_restored -ne $true){throw 'STOP_RESULT'}
 $state.stop_allowed=$true
 Write-Atomic $statePath $state
 [pscustomobject]@{stop_allowed=$true;identity_rechecked=$true}|ConvertTo-Json
}else{
 if($state.desktop_initial -ne 'off' -or $state.desktop_started_by_attempt -ne $true -or $state.restore_invoked -ne $true){throw 'OFF_OWNERSHIP'}
 $result=Get-Content -LiteralPath (Join-Path $taskRoot 'restore.json') -Raw -Encoding UTF8|ConvertFrom-Json
 if($result.outcome -ne 'STOP_RETURNED_ZERO'){throw 'STOP_NOT_CONFIRMED'}
 $absent=$false
 for($index=0;$index -lt 10;$index++){
  $processes=@(Get-Process|Where-Object{$_.ProcessName -match 'docker'})
  if($processes.Count -eq 0){$absent=$true;break}
  Start-Sleep -Seconds 1
 }
 $state|Add-Member -NotePropertyName desktop_restored_off -NotePropertyValue $absent
 $state|Add-Member -NotePropertyName absence_observed_utc -NotePropertyValue ([DateTime]::UtcNow.ToString('o'))
 $state.phase=if($absent){'COMPLETE_DESKTOP_OFF'}else{'OFF_NOT_CONFIRMED'}
 Write-Atomic $statePath $state
 [pscustomobject]@{desktop_restored_off=$absent;utc=$state.absence_observed_utc}|ConvertTo-Json
 if(-not $absent){exit 2}
}
